command.run:
gh issue create --title 'CI Failure: {{failedStep}} - Auto-remediation failed' --body '$(cat <<EOF
## CI Failure Report

**Step:** {{failedStep}}
**Auto-remediation attempts:** {{remediationAttempts}}

{{analysis}}

---
*This issue was created automatically by MiniBob after auto-remediation failed.*
EOF
)' --label 'auto-remediation,needs-human,ci-failure'
